const IDENTITY_SENTENCE_PREFIX_PATTERNS = [
	/^\s*(?:you are|you're)\s+(?:the\s+)?pi\b[^.?!]*[.?!]\s*/i,
	/^\s*(?:you are|you're)\s+(?:an\s+)?(?:ai\s+)?(?:assistant|agent|coding assistant)(?:\s+named)?\s+pi\b[^.?!]*[.?!]\s*/i,
	/^\s*i am pi\b[^.?!]*[.?!]\s*/i,
	/^\s*(?:you are|you're)\b[^.?!]*\b(?:operating|running)\s+(?:inside|within)\s+pi\b[^.?!]*[.?!]\s*/i,
] as const;

const IDENTITY_LINE_PATTERNS = [
	/^\s*(?:you are|you're)\s+(?:the\s+)?pi\b.*$/i,
	/^\s*(?:you are|you're)\s+(?:an\s+)?(?:ai\s+)?(?:assistant|agent|coding assistant)(?:\s+named)?\s+pi\b.*$/i,
	/^\s*(?:assistant|agent|model)\s+(?:name|identity)\s*:\s*pi\b.*$/i,
	/^\s*i am pi\b.*$/i,
	/^\s*(?:you are|you're)\b.*\b(?:operating|running)\s+(?:inside|within)\s+pi\b.*$/i,
] as const;


const NEUTRAL_DOC_ALIASES = getNeutralDocAliasPaths();

function collapseBlankLines(lines: string[]) {
	return lines.reduce<string[]>((result, line) => {
		const normalized = line.trim().length === 0 ? "" : line;
		if (normalized === "" && result[result.length - 1] === "") return result;
		result.push(normalized);
		return result;
	}, []);
}

function stripIdentitySentencePrefix(line: string) {
	for (const pattern of IDENTITY_SENTENCE_PREFIX_PATTERNS) {
		const replaced = line.replace(pattern, "");
		if (replaced !== line) return replaced.trimStart();
	}
	return line;
}

function rewriteReferenceDocumentationLine(line: string) {
	const leadingWhitespace = line.match(/^\s*/)?.[0] ?? "";
	const trimmed = line.trim();
	if (
		/^Pi documentation \(read only when the user asks about pi itself, its SDK, extensions, themes, skills, or TUI\):\s*$/i.test(trimmed)
	) {
		return `${leadingWhitespace}Reference documentation (read only when the user asks about the local coding agent, its SDK, extensions, themes, skills, or TUI):`;
	}
	if (/^-\s*Main documentation:/i.test(trimmed)) {
		return `${leadingWhitespace}- Main documentation: ${NEUTRAL_DOC_ALIASES.readme}`;
	}
	if (/^-\s*Additional docs:/i.test(trimmed)) {
		return `${leadingWhitespace}- Additional docs: ${NEUTRAL_DOC_ALIASES.docs}`;
	}
	if (/^-\s*Examples:/i.test(trimmed)) {
		return `${leadingWhitespace}- Examples: ${NEUTRAL_DOC_ALIASES.examples} (extensions, custom tools, SDK)`;
	}
	if (/^-\s*When asked about:/i.test(trimmed)) {
		return `${leadingWhitespace}- When asked about: extensions (docs/extensions.md, examples/extensions/), themes (docs/themes.md), skills (docs/skills.md), prompt templates (docs/prompt-templates.md), TUI components (docs/tui.md), keybindings (docs/keybindings.md), SDK integrations (docs/sdk.md), custom providers (docs/custom-provider.md), adding models (docs/models.md), packages (docs/packages.md)`;
	}
	if (/^-\s*When working on pi topics,/i.test(trimmed)) {
		return `${leadingWhitespace}- When working on agent topics, read the docs and examples, and follow .md cross-references before implementing`;
	}
	if (/^-\s*Always read pi \.md files completely/i.test(trimmed)) {
		return `${leadingWhitespace}- Always read the .md files completely and follow links to related docs (e.g., tui.md for TUI API details)`;
	}
	return line;
}

export function sanitizeAnthropicCcSystemPrompt(prompt?: string): string | undefined {
	if (!prompt?.trim()) return undefined;
	const filtered: string[] = [];
	for (const line of sanitizeSurrogates(prompt).split(/\r?\n/)) {
		const strippedLine = rewriteReferenceDocumentationLine(stripIdentitySentencePrefix(line));
		const trimmed = strippedLine.trim();
		if (!trimmed) {
			if (!line.trim()) filtered.push(line);
			continue;
		}
		if (IDENTITY_LINE_PATTERNS.some((pattern) => pattern.test(trimmed))) {
			continue;
		}
		filtered.push(strippedLine);
	}

	const cleaned = collapseBlankLines(filtered).join("\n").trim();
	return cleaned || undefined;
}

