import { randomUUID } from "node:crypto";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
// Keep this on Pi's exact compat entrypoint. Its installed jiti loader rewrites
// pi-ai package roots; importing an `api/*` subpath becomes `compat.js/api/*`.
import {
	anthropicMessagesApi,
	type AnthropicOptions,
	type TranscriptContext,
	type Model,
	type SimpleStreamOptions,
} from "@earendil-works/pi-ai/compat";
import { ensureNeutralDocAliases } from "./docAliases";
import { setAnthropicCcBaselineVersion } from "./anthropic-cc/constants";
import { getAnthropicCcProviderConfig } from "./anthropic-cc/providerConfig";
import {
	applyAuthAwareAnthropicBetaFlags,
	buildAuthAwareAnthropicHeaders,
	buildAnthropicOAuthHeaders,
} from "./parity";
import {
	buildSyntheticMetadataUserId,
	ensureAccountUuid,
	ensureDeviceId,
	patchAnthropicOAuthPayload,
} from "./payload";
import { getClaudeCodeVersion } from "./version";

const { stream: streamAnthropic, streamSimple: streamSimpleAnthropic } = anthropicMessagesApi();

const FULL_ANTHROPIC_OPTION_KEYS = [
	"thinkingEnabled",
	"thinkingBudgetTokens",
	"effort",
	"thinkingDisplay",
	"interleavedThinking",
	"toolChoice",
	"client",
] as const;

function normalizeBuiltinBetaHeader<T extends string | null>(
	source: Record<string, T> | undefined,
): Record<string, T> {
	const result: Record<string, T> = {};
	for (const [name, value] of Object.entries(source ?? {})) {
		result[name.toLowerCase() === "anthropic-beta" ? "anthropic-beta" : name] = value;
	}
	return result;
}

function streamBuiltinAnthropic(
	model: Model<any>,
	context: TranscriptContext,
	options: SimpleStreamOptions | undefined,
	defaultBetas: string,
) {
	const modelHeaders = normalizeBuiltinBetaHeader(model.headers);
	const optionHeaders = normalizeBuiltinBetaHeader(options?.headers);
	const requestModel = model.headers ? { ...model, headers: modelHeaders } : model;
	const effectiveBeta = Object.hasOwn(optionHeaders, "anthropic-beta")
		? optionHeaders["anthropic-beta"]
		: modelHeaders["anthropic-beta"];
	const hasExplicitBeta = effectiveBeta !== undefined;
	if (hasExplicitBeta) {
		const adjusted = buildAuthAwareAnthropicHeaders(
			{ ...modelHeaders, ...optionHeaders, "anthropic-beta": effectiveBeta },
			options?.apiKey,
		);
		optionHeaders["anthropic-beta"] = adjusted["anthropic-beta"]!;
	}
	const headers = buildAuthAwareAnthropicHeaders(optionHeaders, options?.apiKey);
	const onPayload: NonNullable<SimpleStreamOptions["onPayload"]> = async (payload, callbackModel) => {
		const params = payload as Record<string, any>;
		if (!hasExplicitBeta) {
			const flags = [
				...defaultBetas.split(","),
				...(params.betas ?? []),
			];
			const seen = new Set<string>();
			const betaHeader = flags
				.map((flag: string) => flag.trim())
				.filter((flag: string) => {
					const key = flag.toLowerCase();
					if (!key || seen.has(key)) return false;
					seen.add(key);
					return true;
				})
				.join(",");
			const betaHeaders = buildAuthAwareAnthropicHeaders(
				{ ...modelHeaders, ...headers, "anthropic-beta": betaHeader },
				options?.apiKey,
			);
			params.betas = (betaHeaders["anthropic-beta"] ?? "").split(",").filter(Boolean);
		}
		const replacement = await options?.onPayload?.(params, callbackModel);
		return replacement === undefined ? params : replacement;
	};
	const usesFullApi = FULL_ANTHROPIC_OPTION_KEYS.some((key) =>
		Object.hasOwn(options ?? {}, key),
	);
	if (usesFullApi) {
		return streamAnthropic(requestModel, context, {
			...(options as AnthropicOptions),
			headers,
			onPayload,
		});
	}
	return streamSimpleAnthropic(requestModel, context, { ...options, headers, onPayload });
}

export default async function (pi: ExtensionAPI) {
	const { version, found } = getClaudeCodeVersion();
	setAnthropicCcBaselineVersion(version);
	const sessionId = randomUUID();
	const metadataUserId = buildSyntheticMetadataUserId(
		ensureDeviceId(),
		ensureAccountUuid(),
		sessionId,
	);
	let aliasWarning: string | undefined;
	try {
		const aliasResult = ensureNeutralDocAliases();
		const problems = Object.entries(aliasResult.leaves).filter(
			([, status]) => status === "skipped-occupied" || status === "failed",
		);
		if (problems.length > 0) {
			aliasWarning = `Claude Code header: doc aliases not linked (${problems
				.map(([leaf, status]) => `${leaf}: ${status}`)
				.join(", ")})`;
		}
	} catch (error) {
		aliasWarning = `Claude Code header: doc alias setup failed (${
			error instanceof Error ? error.message : String(error)
		})`;
	}

	const { "anthropic-beta": defaultBetas, ...identityHeaders } =
		buildAnthropicOAuthHeaders(version, sessionId);
	pi.registerProvider("anthropic", {
		api: "anthropic-messages",
		headers: identityHeaders,
		streamSimple: (model, context, options) =>
			streamBuiltinAnthropic(model, context, options, defaultBetas),
	});

	pi.on("before_provider_request", (event) =>
		patchAnthropicOAuthPayload(event.payload, metadataUserId),
	);
	pi.on("before_provider_headers", (event) => {
		applyAuthAwareAnthropicBetaFlags(event.headers);
	});

	pi.registerProvider("anthropic-cc", await getAnthropicCcProviderConfig());

	pi.on("session_shutdown", async () => {
		const oauth = await import("./anthropic-cc/oauth");
		await oauth.cancelAnthropicCcOAuthOperations();
	});

	pi.on("session_start", async (_event, ctx) => {
		const msg = found
			? `Claude Code header: using version ${version}`
			: `Claude Code header: claude not found, using fallback ${version}`;
		ctx.ui.notify(msg, "info");
		if (aliasWarning) ctx.ui.notify(aliasWarning, "warning");
	});
}

import { join } from "node:path";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";
import {
	ensureSecureDir,
	getPiAgentDir,
	readSecureTextFile,
	writeSecureTextFile,
} from "./agentDir";
export const CLAUDE_CODE_IDENTITY_PROMPT = "You are Claude Code, Anthropic's official CLI for Claude.";
export const CLAUDE_CODE_FALLBACK_OUTPUT_EFFORT = "medium";

export function resolveClaudeCodeOutputEffort(modelId: string): "medium" | "xhigh" {
	if (
		modelId.includes("claude-opus-4-8") ||
		modelId.includes("claude-opus-4.8") ||
		modelId.includes("claude-opus-4-7") ||
		modelId.includes("claude-opus-4.7") ||
		modelId.includes("claude-fable-5")
	) {
		return "xhigh";
	}
	return CLAUDE_CODE_FALLBACK_OUTPUT_EFFORT;
}
type StoredIdentity = {
	deviceId?: string;
	accountUuid?: string;
};

export function getIdentityStoragePath(): string {
	return join(getPiAgentDir(), "pi-claude-header", "identity.json");
}

function readStoredIdentity(path = getIdentityStoragePath()): StoredIdentity {
	try {
		const parsed = JSON.parse(readSecureTextFile(path)) as StoredIdentity;
		return parsed;
	} catch {
		return {};
	}
}

function writeStoredIdentity(path: string, identity: StoredIdentity): void {
	ensureSecureDir(dirname(path));
	writeSecureTextFile(path, JSON.stringify(identity, null, 2));
}

export function ensureDeviceId(path = getIdentityStoragePath()): string {
	const identity = readStoredIdentity(path);
	if (identity.deviceId) return identity.deviceId;

	const deviceId = randomUUID();
	writeStoredIdentity(path, { ...identity, deviceId });
	return deviceId;
}

export function ensureAccountUuid(path = getIdentityStoragePath()): string {
	const identity = readStoredIdentity(path);
	if (identity.accountUuid) return identity.accountUuid;

	const accountUuid = randomUUID();
	writeStoredIdentity(path, { ...identity, accountUuid });
	return accountUuid;
}

export function buildSyntheticMetadataUserId(
	deviceId: string,
	accountUuid: string,
	sessionId: string,
): string {
	return JSON.stringify({
		device_id: deviceId,
		account_uuid: accountUuid,
		session_id: sessionId,
	});
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function buildPatchedOutputConfig(payload: Record<string, unknown>): Record<string, unknown> | undefined {
	const thinking = isRecord(payload.thinking) ? payload.thinking : undefined;
	if (thinking?.type !== "adaptive") return undefined;

	const outputConfig = isRecord(payload.output_config) ? payload.output_config : undefined;
	if (typeof outputConfig?.effort === "string" && outputConfig.effort.length > 0) return undefined;
	const modelId = typeof payload.model === "string" ? payload.model : "";
	// docs/opus-5-baseline-decision.md records no qualifying capture. Do not
	// infer an implicit effort from supported thinking levels.
	if (
		modelId.includes("claude-opus-5") ||
		modelId.includes("claude-opus-5.")
	) {
		return undefined;
	}
	return {
		...(outputConfig ?? {}),
		effort: resolveClaudeCodeOutputEffort(modelId),
	};
}

export function isAnthropicOAuthPayload(payload: unknown): payload is Record<string, unknown> {
	if (!isRecord(payload)) return false;
	if (typeof payload.model !== "string") return false;
	if (!Array.isArray(payload.messages)) return false;
	if (!Array.isArray(payload.system) || payload.system.length === 0) return false;

	const firstSystemBlock = payload.system[0];
	if (!isRecord(firstSystemBlock)) return false;

	return firstSystemBlock.type === "text" && firstSystemBlock.text === CLAUDE_CODE_IDENTITY_PROMPT;
}

export function patchAnthropicOAuthPayload(payload: unknown, metadataUserId: string): unknown {
	if (!isAnthropicOAuthPayload(payload)) return payload;

	const metadata = isRecord(payload.metadata) ? payload.metadata : undefined;
	const nextMetadata =
		typeof metadata?.user_id === "string" && metadata.user_id.length > 0
			? metadata
			: {
				...(metadata ?? {}),
				user_id: metadataUserId,
			};

	const nextOutputConfig = buildPatchedOutputConfig(payload);
	const metadataChanged = nextMetadata !== metadata;

	if (!metadataChanged && !nextOutputConfig) return payload;

	return {
		...payload,
		...(metadataChanged ? { metadata: nextMetadata } : {}),
		...(nextOutputConfig ? { output_config: nextOutputConfig } : {}),
	};
}
